        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            words[i] = br.readLine().trim();
            maxLen = Math.max(maxLen, words[i].length());
        }

        int L = maxLen;
        int states = 1 << L;

        int[] len = new int[n];
        for (int i = 0; i < n; i++) len[i] = words[i].length();

        long[][] T = new long[states][states];

        for (int mask = 0; mask < states; mask++) {
            int[] pos = new int[L];
            for (int i = 0; i < L; i++) {
                if (((mask >> i) & 1) == 0) {
                    pos[i] = i;
                } else {
                    pos[i] = pos[i - 1];
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (words[i].charAt(0) != words[j].charAt(0)) continue;
                    int len1 = len[i], len2 = len[j];
                    int maxLenWord = Math.max(len1, len2);
                    int newMask = 0;
                    boolean ok = true;
                    for (int k = 0; k < maxLenWord; k++) {
                        char c1 = k < len1 ? words[i].charAt(k) : 0;
                        char c2 = k < len2 ? words[j].charAt(k) : 0;
                        if (c1 != c2) {
                            ok = false;
                            break;
                        }
                        int p = pos[k];
                        newMask |= 1 << p;
                    }
                    if (ok) {
                        T[mask][newMask] = (T[mask][newMask] + 1) % MOD;
                    }
                }
            }
        }

        long[][] M = new long[states][states];
        for (int i = 0; i < states; i++)
            System.arraycopy(T[i], 0, M[i], 0, states);

        long[][] R = new long[states][states];
        for (int i = 0; i < states; i++) R[i][i] = 1;

        long exp = m;
        while (exp > 0) {
            if ((exp & 1) == 1) R = mul(R, M);
            M = mul(M, M);
            exp >>= 1;
        }

        long ans = R[0][states - 1] % MOD;
        System.out.println(ans);
    }

    static long[][] mul(long[][] A, long[][] B) {
        int n = A.length;
        long[][] C = new long[n][n];
        for (int i = 0; i < n; i++) {
            long[] Ai = A[i];
            long[] Ci = C[i];
            for (int k = 0; k < n; k++) {
                long aik = Ai[k];
                if (aik == 0) continue;
                long[] Bk = B[k];
                for (int j = 0; j < n; j++) {
                    Ci[j] = (Ci[j] + aik * Bk[j]) % MOD;
                }
            }
        }
        return C;
    }
}

