public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        long m = fs.nextLong();

        String[] words = new String[n];
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            words[i] = fs.next();
            maxLen = Math.max(maxLen, words[i].length());
        }

        // Build all possible segments (word occurrences) and transitions
        // State is last up to 4 letters (since word length <=5, overlap up to 4)
        // Represent state as string; map to id
        HashMap<String, Integer> stateId = new HashMap<>();
        ArrayList<String> states = new ArrayList<>();
        // empty state
        stateId.put("", 0);
        states.add("");

        // BFS generate all states reachable by appending words up to length 5
        Queue<String> q = new ArrayDeque<>();
        q.add("");
        while (!q.isEmpty()) {
            String s = q.poll();
            for (String w : words) {
                String ns = s + w;
                if (ns.length() > 4) ns = ns.substring(ns.length() - 4);
                if (!stateId.containsKey(ns)) {
                    stateId.put(ns, states.size());
                    states.add(ns);
                    q.add(ns);
                }
            }
        }
        int S = states.size();

        // For each state, compute transitions by placing a word starting at next position
        // Also record resulting string segment and new state
        class Trans {
            int to;
            String seg;
            Trans(int t, String s) { to = t; seg = s; }
        }
        ArrayList<Trans>[] trans = new ArrayList[S];
        for (int i = 0; i < S; i++) trans[i] = new ArrayList<>();
        for (int i = 0; i < S; i++) {
            String s = states.get(i);
            for (String w : words) {
                String ns = s + w;
                String seg = w;
                if (ns.length() > 4) ns = ns.substring(ns.length() - 4);
                int nid = stateId.get(ns);
                trans[i].add(new Trans(nid, seg));
            }
        }

        // DP over positions using matrix exponentiation on combined automaton of two hints
        // Combined state: (stateA, stateB, last up to 4 letters of string)
        // But m up to 1e9, need linear recurrence on length only.
        // Observation: number of strings of length m that can be segmented in two ways
        // equals sum over all strings of count(hintsA) * count(hintsB).
        // This equals sum over all segmentations pairs; each pair defines string uniquely.
        // So we just count number of pairs of segmentations of length m, independent of letters.
        // Each segmentation is tiling of length m with word lengths.
        // So answer = (number of tilings of length m with given word lengths)^2.

        int[] lens = new int[n];
        for (int i = 0; i < n; i++) lens[i] = words[i].length();

        int maxWord = 0;
        for (int l : lens) maxWord = Math.max(maxWord, l);

        // DP recurrence: f[x] = sum f[x - len_i]
        // Need f[m], m up to 1e9, len_i <=5, n<=8 -> order <=5 linear recurrence.
        int k = maxWord;
        long[] init = new long[k];
        init[0] = 1;
        for (int i = 1; i < k; i++) {
            long val = 0;
            for (int l : lens) {
                if (i - l >= 0) val = (val + init[i - l]) % MOD;
            }
            init[i] = val;
        }
        if (m < k) {
            long ans = init[(int)m];
            ans = ans * ans % MOD;
            System.out.println(ans);
            return;
        }

        long[] coef = new long[k];
        for (int l : lens) {
            coef[l - 1] = (coef[l - 1] + 1) % MOD;
        }

        long[][] mat = new long[k][k];
        for (int i = 0; i < k; i++) mat[0][i] = coef[i];
        for (int i = 1; i < k; i++) mat[i][i - 1] = 1;

        long p = m - (k - 1);
        long[][] mp = matPow(mat, p);

        long[] vec = new long[k];
        for (int i = 0; i < k; i++) vec[i] = init[k - 1 - i];

        long fm = 0;
        for (int i = 0; i < k; i++) {
            fm = (fm + mp[0][i] * vec[i]) % MOD;
        }

        long ans = fm * fm % MOD;
        System.out.println(ans);
    }

    static long[][] matMul(long[][] a, long[][] b) {
        int n = a.length;
        long[][] r = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                long v = a[i][k];
                if (v == 0) continue;
                for (int j = 0; j < n; j++) {
                    r[i][j] = (r[i][j] + v * b[k][j]) % MOD;
                }
            }
        }
        return r;
    }

    static long[][] matPow(long[][] a, long e) {
        int n = a.length;
        long[][] r = new long[n][n];
        for (int i = 0; i < n; i++) r[i][i] = 1;
        long[][] base = a;
        while (e > 0) {
            if ((e & 1) == 1) r = matMul(r, base);
            base = matMul(base, base);
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;
        FastScanner(InputStream is) { in = is; }
        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c <= ' ') ;
            if (c == -1) return null;
            do {
                sb.append((char)c);
                c = read();
            } while (c > ' ');
            return sb.toString();
        }
        int nextInt() throws IOException { return Integer.parseInt(next()); }
        long nextLong() throws IOException { return Long.parseLong(next()); }
    }
}

