public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        String[] words = new String[n];
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            words[i] = br.readLine().trim();
            maxLen = Math.max(maxLen, words[i].length());
        }

        // Precompute transitions
        int L = maxLen;
        int S = 1 << L; // number of states

        long[] f = new long[S]; // f[s] = number of strings for state s
        long[][] g = new long[S][S]; // g[s][t] = number of ways to choose two segmentations

        // Precompute f[s]
        for (int s = 0; s < S; s++) {
            long cnt = 0;
            for (String w : words) {
                int len = w.length();
                int mask = ((1 << len) - 1) << (L - len);
                if ((s & mask) == mask) cnt++;
            }
            f[s] = cnt % MOD;
        }

        // Precompute g[s][t]
        for (int s = 0; s < S; s++) {
            for (int t = 0; t < S; t++) {
                long cnt = 0;
                for (String w : words) {
                    int len = w.length();
                    int mask = ((1 << len) - 1) << (L - len);
                    boolean ok1 = (s & mask) == mask;
                    boolean ok2 = (t & mask) == mask;
                    if (ok1 && ok2) cnt++;
                }
                g[s][t] = cnt % MOD;
            }
        }

        // Build transition matrix T of size S*S
        long[][] T = new long[S][S];
        for (int s = 0; s < S; s++) {
            for (int t = 0; t < S; t++) {
                long val = (f[t] * f[t]) % MOD;
                val = (val - g[s][t] + MOD) % MOD;
                T[s][t] = val;
            }
        }

        // Matrix exponentiation of T^m
        long[][] res = matPow(T, m);

        // Initial vector v0: only state 0 has 1
        long ans = 0;
        for (int s = 0; s < S; s++) {
            ans = (ans + res[0][s]) % MOD;
        }

        System.out.println(ans);
    }

    static long[][] matMul(long[][] A, long[][] B) {
        int n = A.length;
        long[][] C = new long[n][n];
        for (int i = 0; i < n; i++) {
            long[] Ai = A[i];
            long[] Ci = C[i];
            for (int k = 0; k < n; k++) {
                long aik = Ai[k];
                if (aik == 0) continue;
                long[] Bk = B[k];
                for (int j = 0; j < n; j++) {
                    Ci[j] = (Ci[j] + aik * Bk[j]) % MOD;
                }
            }
        }
        return C;
    }

    static long[][] matPow(long[][] A, long exp) {
        int n = A.length;
        long[][] res = new long[n][n];
        for (int i = 0; i < n; i++) res[i][i] = 1;
        long[][] base = A;
        while (exp > 0) {
            if ((exp & 1) == 1) res = matMul(res, base);
            base = matMul(base, base);
            exp >>= 1;
        }
        return res;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        long m = fs.nextLong();
        String[] words = new String[n];
        for (int i = 0; i < n; i++) words[i] = fs.next();
        int maxLen = 5;

        // Precompute all possible segments (words) and their lengths
        int[] len = new int[n];
        for (int i = 0; i < n; i++) len[i] = words[i].length();

        // DP for number of tilings of length L with given word lengths
        // L up to 5
        long[] tilings = new long[maxLen + 1];
        tilings[0] = 1;
        for (int i = 1; i <= maxLen; i++) {
            long sum = 0;
            for (int j = 0; j < n; j++) {
                if (i >= len[j]) sum += tilings[i - len[j]];
            }
            tilings[i] = sum;
        }

        // DP for number of pairs of tilings of length L and resulting strings
        // We need counts for each possible length 1..5
        // For each length L, we compute:
        // totalPairs[L] = sum over all strings S of (waysTop(S) * waysBottom(S))
        // where waysTop(S) is number of tilings of S with dictionary words.
        // But brute over strings is impossible. Instead, we use DP over positions
        // with states representing partial overlaps of segments.
        // However, since maxLen is 5 and words are length <=5, we can brute over all strings of length <=5
        // alphabet size 26, 26^5 is too big. Need combinatorial DP.

        // We instead count directly number of (string, tilingTop, tilingBottom) triples of length L.
        // This equals number of ways to place segments for top and bottom and assign letters consistently.
        // For each position, constraints come from segments covering it.
        // We can model this as DP over position with states describing which segments are currently active.
        // But segments can start and end; since words length <=5 and L<=5, we can brute all segment placements.

        // Enumerate all possible tilings for top and bottom for length L (using word indices and positions),
        // then count number of strings compatible with both tilings.
        // Number of tilings for length <=5 is small; we can generate recursively.

        List<List<int[]>> tilingsByLen = new ArrayList<>();
        for (int L = 0; L <= maxLen; L++) tilingsByLen.add(new ArrayList<>());
        // Each tiling is list of segments: [start, wordIndex]
        for (int L = 1; L <= maxLen; L++) {
            generateTilings(L, 0, new ArrayList<>(), tilingsByLen.get(L), len);
        }

        long[] totalPairs = new long[maxLen + 1];
        for (int L = 1; L <= maxLen; L++) {
            List<int[]> topTilings = tilingsByLen.get(L);
            List<int[]> bottomTilings = tilingsByLen.get(L);
            long sum = 0;
            for (int[] top : topTilings) {
                for (int[] bottom : bottomTilings) {
                    int ways = countStringsForTilings(L, top, bottom, words);
                    sum += ways;
                }
            }
            totalPairs[L] = sum % MOD;
        }

        // Now we have totalPairs[L] for L<=5.
        // For general m, chainword instances correspond to concatenation of independent blocks,
        // but segments cannot cross block boundaries. We can treat each position as covered by some word;
        // effectively, the structure is tilings of length m with words, for both top and bottom,
        // and strings consistent. This is equivalent to counting ways to partition m into blocks of length 1..5,
        // where each block contributes totalPairs[L].

        // So answer is number of ways to tile length m with blocks of size 1..5, where each block of size L
        // contributes factor totalPairs[L]. This is linear recurrence with exponentiation via DP with matrix.

        int K = maxLen;
        long[] base = new long[K];
        // dp[i] = sum_{L=1..5} totalPairs[L] * dp[i-L]
        // We build companion matrix of size 5x5.
        long[][] mat = new long[K][K];
        for (int i = 0; i < K; i++) {
            if (i == 0) {
                for (int L = 1; L <= K; L++) {
                    mat[0][L - 1] = totalPairs[L] % MOD;
                }
            } else {
                mat[i][i - 1] = 1;
            }
        }

        // initial vector dp[1..5]
        long[] dpInit = new long[K];
        for (int i = 1; i <= K; i++) {
            long val = 0;
            for (int L = 1; L <= i; L++) {
                val += totalPairs[L] * (L == i ? 1 : tilings[i - L]);
            }
            dpInit[i - 1] = val % MOD;
        }

        if (m <= K) {
            System.out.println(dpInit[(int) m - 1]);
            return;
        }

        long exp = m - K;
        long[][] matPow = matPow(mat, exp);
        long[] res = mulMatVec(matPow, dpInit);
        System.out.println(res[0] % MOD);
    }

    static void generateTilings(int L, int pos, List<int[]> cur, List<int[]> res, int[] len) {
        if (pos == L) {
            int[] arr = new int[cur.size() * 2];
            int idx = 0;
            for (int[] seg : cur) {
                arr[idx++] = seg[0];
                arr[idx++] = seg[1];
            }
            res.add(arr);
            return;
        }
        for (int w = 0; w < len.length; w++) {
            int l = len[w];
            if (pos + l <= L) {
                cur.add(new int[]{pos, w});
                generateTilings(L, pos + l, cur, res, len);
                cur.remove(cur.size() - 1);
            }
        }
    }

    static int countStringsForTilings(int L, int[] top, int[] bottom, String[] words) {
        char[] s = new char[L];
        Arrays.fill(s, '?');
        if (!applyTilings(L, s, top, words)) return 0;
        if (!applyTilings(L, s, bottom, words)) return 0;
        int free = 0;
        for (int i = 0; i < L; i++) if (s[i] == '?') free++;
        long ways = 1;
        for (int i = 0; i < free; i++) ways = (ways * 26) % MOD;
        return (int) ways;
    }

    static boolean applyTilings(int L, char[] s, int[] tiling, String[] words) {
        for (int i = 0; i < tiling.length; i += 2) {
            int start = tiling[i];
            int w = tiling[i + 1];
            String word = words[w];
            for (int j = 0; j < word.length(); j++) {
                int pos = start + j;
                char c = word.charAt(j);
                if (s[pos] == '?' || s[pos] == c) s[pos] = c;
                else return false;
            }
        }
        return true;
    }

    static long[][] matMul(long[][] a, long[][] b) {
        int n = a.length;
        long[][] r = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                long v = a[i][k];
                if (v == 0) continue;
                for (int j = 0; j < n; j++) {
                    r[i][j] = (r[i][j] + v * b[k][j]) % MOD;
                }
            }
        }
        return r;
    }

    static long[][] matPow(long[][] a, long e) {
        int n = a.length;
        long[][] r = new long[n][n];
        for (int i = 0; i < n; i++) r[i][i] = 1;
        long[][] base = a;
        while (e > 0) {
            if ((e & 1) == 1) r = matMul(r, base);
            base = matMul(base, base);
            e >>= 1;
        }
        return r;
    }

    static long[] mulMatVec(long[][] m, long[] v) {
        int n = m.length;
        long[] r = new long[n];
        for (int i = 0; i < n; i++) {
            long sum = 0;
            for (int j = 0; j < n; j++) {
                sum = (sum + m[i][j] * v[j]) % MOD;
            }
            r[i] = sum;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c <= ' ') ;
            if (c == -1) return null;
            do {
                sb.append((char) c);
                c = read();
            } while (c > ' ');
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
