public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        long m = fs.nextLong();

        String[] words = new String[n];
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            words[i] = fs.next();
            maxLen = Math.max(maxLen, words[i].length());
        }

        int L = maxLen;
        int states = 1 << L;

        long[][] T = new long[states][states];

        for (int mask = 0; mask < states; mask++) {
            for (int w = 0; w < n; w++) {
                int len = words[w].length();
                int newMask = ((mask << len) | ((1 << len) - 1)) & (states - 1);
                T[mask][newMask] = (T[mask][newMask] + 1) % MOD;
            }
        }

        long[][] T2 = mul(T, T);

        long[][] Tpow = matPow(T, m);
        long[][] T2pow = matPow(T2, m);

        long[] v0 = new long[states];
        v0[0] = 1;

        long[] v1 = mulVec(Tpow, v0);
        long[] v2 = mulVec(T2pow, v0);

        long sum1 = 0, sum2 = 0;
        for (int i = 0; i < states; i++) {
            sum1 = (sum1 + v1[i]) % MOD;
            sum2 = (sum2 + v2[i]) % MOD;
        }

        long ans = (sum1 * sum1 - sum2) % MOD;
        if (ans < 0) ans += MOD;
        System.out.println(ans);
    }

    static long[][] mul(long[][] A, long[][] B) {
        int n = A.length;
        long[][] C = new long[n][n];
        for (int i = 0; i < n; i++) {
            long[] Ai = A[i];
            long[] Ci = C[i];
            for (int k = 0; k < n; k++) {
                long aik = Ai[k];
                if (aik == 0) continue;
                long[] Bk = B[k];
                for (int j = 0; j < n; j++) {
                    long val = Ci[j] + aik * Bk[j];
                    if (val >= (1L << 61)) val %= MOD;
                    Ci[j] = val;
                }
            }
            for (int j = 0; j < n; j++) Ci[j] %= MOD;
        }
        return C;
    }

    static long[] mulVec(long[][] A, long[] v) {
        int n = A.length;
        long[] res = new long[n];
        for (int i = 0; i < n; i++) {
            long[] Ai = A[i];
            long sum = 0;
            for (int j = 0; j < n; j++) {
                long val = Ai[j] * v[j];
                sum += val;
                if (sum >= (1L << 61)) sum %= MOD;
            }
            res[i] = sum % MOD;
        }
        return res;
    }

    static long[][] matPow(long[][] A, long exp) {
        int n = A.length;
        long[][] res = new long[n][n];
        for (int i = 0; i < n; i++) res[i][i] = 1;
        long[][] base = A;
        while (exp > 0) {
            if ((exp & 1) != 0) res = mul(res, base);
            base = mul(base, base);
            exp >>= 1;
        }
        return res;
    }

